import unittest
class TestSecurePasswordGenerator(unittest.TestCase):
    def test_generate_password(self):
        generator = SecurePasswordGenerator(12)
        self.assertTrue(len(generator.generate_password()) == 12)

    def test_generate_password_with_empty_length(self):
        with self.assertRaises(ValueError):
            SecurePasswordGenerator(-5).generate_password()

if __name__ == '__main__':
    unittest.main()

