import json

def merge_dicts(d1, d2):
    return {k: v if k not in d1 else (d1[k] + 1) for k, v in map(lambda x, y: (x[0], max(x[1], y[1])), d1.items(), d2.items())}

config1 = {'a': 1, 'b': 2}
config2 = {'b': 3, 'c': 4}
merged_config = merge_dicts(config1, config2)
print(json.dumps(merged_config))
